// example usage in docs:
const proxy = StreamProxy.from(runtimeResponse.stream);
for await (const frame of proxy.asAsyncIterator()) {
  if (frame.type === 'control' && frame.code === 'retryable') {
    // optionally hand back so runtime can re-enqueue or route
    await proxy.handback(frame, {route: 'fallback'});
  } else if (frame.type === 'data') {
    // frame.value may be string | Uint8Array | {json}
    render(frame.value);
  }
}
// or: const rs = proxy.asReadableStream(); // still preserves cancellation
